algorithms.pseudocode:
function SATURATE(generators G, closure system S):
    family <- G
    repeat
        new <- empty
        for each P, Q in family:
            J <- cl(P union Q)
            if J not in family: new <- new union {J}
        for each R in family, a in Sigma:
            P <- cl({y | step(y, a) in R})
            if P not in family: new <- new union {P}
        family <- family union new
    until new = empty
    return family

Complexity: O(|R|^2 * |Sigma| * (|X| + T_cl)) per iteration
Space: O(|R| * |X|)
